using System;
using System.IO;
using System.Linq;
namespace MochiDesktop {
 public static class ActionReminderTests {
  static void Assert(bool value,string error){if(!value)throw new Exception(error);}
  public static void Add(Action<string,Action> test,string directory){var now=new DateTime(2026,10,26,12,0,0,DateTimeKind.Utc);
   test("Relative reminder common unit aliases are accepted",delegate{string[][] groups={new[]{"s","sec","secs","second","seconds"},new[]{"m","min","mins","minute","minutes"},new[]{"h","hr","hrs","hour","hours"},new[]{"d","day","days"},new[]{"w","wk","wks","week","weeks"}};double[] factors={1,60,3600,86400,604800};for(int i=0;i<groups.Length;i++)foreach(string unit in groups[i]){var r=Commands.Parse("remind me in 10 "+unit+" to check mail",new StoredState(),now).Reminder;Assert(r!=null&&r.DueUtcTicks==now.AddSeconds(10*factors[i]).Ticks,"Alias failed: "+unit);}});
   test("Compact relative reminder and uppercase aliases work",delegate{var r=Commands.Parse("Remind me in 10MIN to check mail",new StoredState(),now).Reminder;Assert(r!=null&&r.DueUtcTicks==now.AddMinutes(10).Ticks,"Compact min failed");});
   test("Literal URL command explicitly schedules one website action",delegate{var r=Commands.Parse("remind me in 20 min to check https://example.com/path?q=mail&view=full",new StoredState(),now).Reminder;Assert(r!=null&&r.OpenUrlOnDue&&r.ActionUrl=="https://example.com/path?q=mail&view=full"&&r.LastActionClaimUtcTicks==0,"URL action missing");});
   test("Whole long URLs survive independently of short reminder title",delegate{string url="https://example.com/path?q="+new string('a',1400);var r=Commands.Parse("remind me in 20 min to check "+url,new StoredState(),now).Reminder;Assert(r!=null&&r.OpenUrlOnDue&&r.ActionUrl==url&&r.Title.Length<=300,"Long URL was shortened");});
   test("Full URL queries keep nested links and punctuation",delegate{string url="https://example.com/path?q=mail&next=https://other.example/a!";var r=Commands.Parse("remind me in 20 min to check "+url,new StoredState(),now).Reminder;Assert(r!=null&&r.ActionUrl==url,"Whole URL query changed");});
   test("Malicious scheduled URLs cannot opt in",delegate{foreach(string url in new[]{"https://u:p@example.com/","https://example.com\\bad","javascript:alert(1)","file:///C:/Windows/a.exe","data:text/html,bad"}){var result=Commands.Parse("remind me in 5 min to open "+url,new StoredState(),now);Assert(result.Reminder==null||!result.Reminder.OpenUrlOnDue,"Unsafe URL scheduled: "+url);}});
   test("Multiple URLs require a clear single target",delegate{foreach(string body in new[]{"https://one.example/ https://two.example/","https://one.example/ and https://two.example/"})Assert(Commands.Parse("remind me in 1 min to check "+body,new StoredState(),now).Reminder==null,"Multiple targets accepted");});
   test("URL command control characters are rejected",delegate{Assert(Commands.Parse("remind me in 1 min to check https://ex\tample.com",new StoredState(),now).Reminder==null,"Control split URL accepted");});
   test("Notification-only reminders never infer an automatic URL",delegate{var r=ReminderEngine.Create("Imported calendar link https://example.com",now,"none");r.ActionUrl="https://example.com/";Assert(!r.OpenUrlOnDue&&!ReminderActions.Claim(r,r.DueUtcTicks),"External link automatically opted in");});
   test("Manual URL opt in validates before scheduling",delegate{var r=ReminderEngine.Create("Website",now,"none");bool rejected=false;try{ReminderActions.Configure(r,"shell:bad",true);}catch(ArgumentException){rejected=true;}Assert(rejected&&!r.OpenUrlOnDue,"Unsafe manual action accepted");ReminderActions.Configure(r,"https://example.com",true);Assert(r.OpenUrlOnDue&&r.ActionUrl=="https://example.com/","Manual opt in lost");});
   test("Malformed persisted actions become notification-only",delegate{var state=new StoredState();var r=ReminderEngine.Create("Keep reminder",now,"none");r.ActionUrl="file:///bad";r.OpenUrlOnDue=true;state.Reminders.Add(r);StateStore.Normalize(state);Assert(state.Reminders.Count==1&&!r.OpenUrlOnDue&&r.ActionUrl==null,"Invalid action lost whole reminder");});
   test("URL action claim survives restart without repeating",delegate{var state=new StoredState();var r=ReminderEngine.Create("Website",now.AddSeconds(-1),"none");ReminderActions.Configure(r,"https://example.com",true);state.Reminders.Add(r);var due=ReminderEngine.ClaimDue(state,now);Assert(due.Count==1&&due[0].OpenUrlOnDue&&r.LastActionClaimUtcTicks==r.DueUtcTicks,"Action not claimed");var store=new StateStore(Path.Combine(directory,"url-action-restart"));store.Save(state);int opens=0;ReminderActions.ExecuteClaimed(due[0],delegate{opens++;});var loaded=store.Load();Assert(ReminderEngine.ClaimDue(loaded,now.AddMinutes(1)).Count==0&&opens==1&&loaded.Reminders[0].LastActionClaimUtcTicks==r.LastActionClaimUtcTicks,"Duplicate automatic navigation");});
   test("A previously claimed URL is not reopened during reminder recovery",delegate{var state=new StoredState();var r=ReminderEngine.Create("Website",now,"none");ReminderActions.Configure(r,"https://example.com",true);r.LastActionClaimUtcTicks=r.DueUtcTicks;state.Reminders.Add(r);var due=ReminderEngine.ClaimDue(state,now);Assert(due.Count==1&&!due[0].OpenUrlOnDue,"Recovered claim opened again");});
   test("Recurring explicit actions claim once per occurrence",delegate{var state=new StoredState();var r=ReminderEngine.Create("Daily website",now,"daily");ReminderActions.Configure(r,"https://example.com",true);state.Reminders.Add(r);var first=ReminderEngine.ClaimDue(state,now);long next=r.DueUtcTicks;Assert(first[0].OpenUrlOnDue&&ReminderEngine.ClaimDue(state,now).Count==0,"Repeated first action");var second=ReminderEngine.ClaimDue(state,new DateTime(next,DateTimeKind.Utc));Assert(second.Count==1&&second[0].OpenUrlOnDue&&r.LastActionClaimUtcTicks==next,"Next action missing");});
   test("Snooze creates notification only even when title contains link",delegate{var snoozed=ReminderActions.Snooze("Check website","https://example.com/",now.AddMinutes(5));Assert(!snoozed.OpenUrlOnDue&&snoozed.ActionUrl=="https://example.com/"&&snoozed.LastActionClaimUtcTicks==0,"Snooze must retain a manual link without automatic opening");var state=new StoredState();state.Reminders.Add(snoozed);ReminderQueue.Enqueue(state,ReminderEngine.ClaimDue(state,now.AddMinutes(5)));Assert(state.PendingAlerts[0].ActionUrl=="https://example.com/"&&!ReminderActions.Claim(snoozed,snoozed.DueUtcTicks),"Snoozed manual link lost or automatically opened");});
   test("Failed browser action does not block another due reminder",delegate{var state=new StoredState();for(int i=0;i<2;i++){var r=ReminderEngine.Create("Website "+i,now,"none");ReminderActions.Configure(r,"https://example.com/"+i,true);state.Reminders.Add(r);}var due=ReminderEngine.ClaimDue(state,now);int attempts=0;string first=ReminderActions.ExecuteClaimed(due[0],delegate{attempts++;throw new IOException("Unavailable browser");});string second=ReminderActions.ExecuteClaimed(due[1],delegate{attempts++;});Assert(first.Contains("could not")&&second.Contains("sent")&&attempts==2&&ReminderEngine.ClaimDue(state,now).Count==0,"Failed opening escaped or retried");});
   test("Oversized save preserves the last readable state",delegate{var store=new StateStore(Path.Combine(directory,"bounded-action-store"));var small=new StoredState();small.Reminders.Add(ReminderEngine.Create("Keep this reminder",now,"none"));store.Save(small);string prior=File.ReadAllText(store.FilePath);var large=new StoredState();for(int i=0;i<1000;i++){var r=ReminderEngine.Create(new string('t',300),now,"none");ReminderActions.Configure(r,"https://example.com/"+new string('a',1900),true);large.Reminders.Add(r);}bool rejected=false;try{store.Save(large);}catch(InvalidDataException){rejected=true;}Assert(rejected&&File.ReadAllText(store.FilePath)==prior&&store.Load().Reminders[0].Title=="Keep this reminder","Oversized state replaced valid data");});
   test("Unread notice retains URL result without dispatching it again",delegate{var state=new StoredState();var r=ReminderEngine.Create("Website",now,"none");ReminderActions.Configure(r,"https://example.com",true);state.Reminders.Add(r);ReminderQueue.Enqueue(state,ReminderEngine.ClaimDue(state,now));Assert(state.PendingAlerts.Count==1&&state.PendingAlerts[0].ActionUrl=="https://example.com/","Bubble missing action details");ReminderQueue.Normalize(state);Assert(state.PendingAlerts.Count==1&&ReminderEngine.ClaimDue(state,now).Count==0,"Unread queue replayed action");});
  }
 }
}
